<!--vbase-->
<template>
  <q-tooltip class="fl-tip">
    <div class="fl-tip__header">
      <span class="fl-tip__title">{{ row.field_name || '—' }}</span>
      <span v-if="row.field_type" class="fl-tip__type">
        {{ row.field_type }}
      </span>
    </div>

    <div class="fl-tip__result-row">
      <span class="fl-tip__eyebrow">{{ $t('displayed_label') }}</span>
      <span class="fl-tip__result">{{ resolvedLabel || '—' }}</span>
    </div>

    <div class="fl-tip__section">{{ $t('label_resolution_order') }}</div>

    <div class="fl-steps">
      <div
        v-for="(step, index) in steps"
        :key="step.key"
        class="fl-step"
        :class="step.used ? 'fl-step--applied' : 'fl-step--skipped'"
      >
        <span class="fl-step__marker">{{ index + 1 }}</span>

        <div class="fl-step__body">
          <div class="fl-step__title-row">
            <span class="fl-step__name">{{ step.source }}</span>
            <span v-if="step.used" class="fl-step__tag">{{ $t('applied') }}</span>
          </div>

          <div
            class="fl-step__value"
            :class="{ 'fl-step__value--mono': step.mono }"
          >
            {{ step.value }}
            <template v-if="step.resolved">
              &rarr; &ldquo;{{ step.resolved }}&rdquo;
            </template>
          </div>

          <div v-if="!step.used" class="fl-step__reason">
            {{ step.reason }}
          </div>
        </div>
      </div>
    </div>
  </q-tooltip>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { getFieldTranslationKey } from 'src/utils/fieldTranslationKey';

export default defineComponent({
  name: 'FieldLabelTooltip',
  mixins: [displayFieldLabel],
  props: {
    row: {
      type: Object as PropType<Record<string, any>>,
      required: true,
    },
  },
  computed: {
    resolvedLabel(): string {
      return this.getFieldLabel(this.row, '');
    },

    // One walk of displayFieldLabel's precedence, done once. The individual
    // values are derivation plumbing, not state the template asks for, so they
    // stay inside this object rather than becoming computeds of their own.
    resolution(): dynamicObj {
      const row = this.row;
      const fieldKey =
        row.field_name || row.document_name || row.document_key || '';
      // additional_attributes first, then the legacy column.
      const translationKey = getFieldTranslationKey(row);
      const lookupKey = translationKey || fieldKey;
      const translation = this.translateLabel(lookupKey);
      // translateLabel echoes the key back when nothing matched.
      const hasTranslation = !!lookupKey && translation !== lookupKey;

      return {
        fieldKey,
        translationKey,
        translation,
        hasTranslation,
        // Whether the field name would have resolved on its own — only needed
        // to explain step 2. With no key set the lookup already WAS the field
        // name, so the answer is the lookup's own result.
        nameResolves: translationKey
          ? !!fieldKey && this.translateLabel(fieldKey) !== fieldKey
          : hasTranslation,
        // Index of the step displayFieldLabel actually took, or -1.
        appliedIndex: [
          !!translationKey && hasTranslation,
          !translationKey && hasTranslation,
          !hasTranslation && !!row.field_label,
          !hasTranslation && !row.field_label && !!row.title,
        ].indexOf(true),
      };
    },

    steps(): dynamicObj[] {
      const row = this.row;
      const { fieldKey, translationKey, translation, appliedIndex } =
        this.resolution;

      return [
        {
          key: 'translation_key',
          source: this.$t('translation_key_label'),
          value: translationKey,
          resolved: appliedIndex === 0 ? translation : '',
          used: appliedIndex === 0,
          mono: true,
          reason: this.stepReason(0),
        },
        {
          key: 'field_name',
          source: this.$t('field_name'),
          value: fieldKey,
          resolved: appliedIndex === 1 ? translation : '',
          used: appliedIndex === 1,
          mono: true,
          reason: this.stepReason(1),
        },
        {
          key: 'field_label',
          source: this.$t('field_label'),
          value: row.field_label || '',
          resolved: '',
          used: appliedIndex === 2,
          mono: false,
          reason: this.stepReason(2),
        },
        {
          key: 'title',
          source: this.$t('title'),
          value: row.title || '',
          resolved: '',
          used: appliedIndex === 3,
          mono: false,
          reason: this.stepReason(3),
        },
      ];
    },
  },
  methods: {
    // "Not reached" means strictly: an earlier step already won, so this one
    // was never evaluated. Anything at or before the winner has to say why it
    // failed instead.
    notReached(index: number): boolean {
      const applied = this.resolution.appliedIndex;
      return applied !== -1 && index > applied;
    },

    stepReason(index: number): string {
      if (this.notReached(index)) {
        return this.$t('label_not_reached');
      }

      const { fieldKey, translationKey, nameResolves } = this.resolution;

      if (index === 0) {
        return translationKey
          ? this.$t('label_no_translation_by_key')
          : this.$t('label_no_text_found');
      }

      if (index === 1) {
        if (!fieldKey) {
          return this.$t('label_no_text_found');
        }
        // It would have resolved — the key set above simply took precedence.
        if (nameResolves) {
          return this.$t('label_not_reached');
        }
        return this.$t('label_no_translation_by_field_name');
      }

      // A static source that is reached and non-empty always wins, so the only
      // way to reach one and not apply it is for it to be empty.
      return this.$t('label_no_text_found');
    },
  },
});
</script>

